/* browserstack_accessibility_automation_script */
const callback = arguments[arguments.length - 1];
const payloadToSend = arguments[0];
const middlewareStartTime = performance.now();

function waitForScannerReadiness(retryCount = 100, retryInterval = 100) {
  return new Promise((resolve, reject) => {
    let count = 0;
    const intervalID = setInterval(() => {
      if (count > retryCount) {
        clearInterval(intervalID);
        reject(new Error('Accessibility Automation Scanner is not ready on the page.'));
      } else if (findAccessibilityAutomationElement()) {
        clearInterval(intervalID);
        resolve({ status: 'success' });
      } else {
        count += 1;
      }
    }, retryInterval);
  });
}

function scanForAccessibility() {
  const scanStartTime = performance.now();
  const requestEvent = new CustomEvent('A11Y_SCAN', {
    detail: {
      ...payloadToSend,
      middlewareStartTime,
      scanStartTime,
      readinessCheckTime: scanStartTime - middlewareStartTime
    }
  });
  const responseEvent = 'A11Y_SCAN_FINISHED';

  const responseEventListener = () => {
    window.removeEventListener(responseEvent, responseEventListener);
    console.info("Accessibility Automation Scanner completed the scan.");
    callback({ success: true, msg: "Accessibility Automation Scanner completed the scan." });
  };

  window.addEventListener(responseEvent, responseEventListener);

  console.info("Requesting Accessibility Automation Scanner to perform a scan.");
  window.dispatchEvent(requestEvent);
}

function findAccessibilityAutomationElement() {
  return document.querySelector('#accessibility-automation-element');
}

const isHttpOrHttps = /^(http|https):$/.test(window.location.protocol);

if (findAccessibilityAutomationElement()) {
  console.info("Scanner is already ready on the page.");
  scanForAccessibility();
} else if (isHttpOrHttps) {
  waitForScannerReadiness()
    .then((result) => {
      if (result.status === 'success') {
        console.info("Scanner is now ready on the page after multiple retries.");
        scanForAccessibility();
      }
    })
    .catch((error) => {
      console.error("Scanner is not ready on the page after multiple retries.", error);
      callback({ success: false, msg: "Scanner is not ready on the page after multiple retries." });
    });
} else {
  console.warn("Unable to perform accessibility scan, Invalid URL.");
  callback({ success: false, msg: "Unable to perform accessibility scan, Invalid URL." });
}
